mapper.select:
SELECT id, bus_no, name, type_enum, credit_code, legal_representative, phone, status_enum, display_order, DATE_FORMAT(updated_at, '%Y-%m-%d %H:%i:%s') AS updatedAt FROM cus_supplier
is_deleted = 0 AND tenant_id = #{tenantId}
AND ( name LIKE CONCAT('%', #{query.keyword}, '%') OR bus_no LIKE CONCAT('%', #{query.keyword}, '%') OR credit_code LIKE CONCAT('%', #{query.keyword}, '%') OR py_str LIKE CONCAT('%', #{query.keyword}, '%') OR wb_str LIKE CONCAT('%', #{query.keyword}, '%') )
AND bus_no = #{query.busNo}
AND name LIKE CONCAT('%', #{query.name}, '%')
AND credit_code = #{query.creditCode}
AND type_enum = #{query.typeEnum}
AND UPPER(status_enum) = 'ACTIVE'
AND UPPER(status_enum) = 'INACTIVE'
AND org_id = #{query.orgId}
AND py_str LIKE CONCAT('%', #{query.pyStr}, '%')
AND wb_str LIKE CONCAT('%', #{query.wbStr}, '%')
AND phone LIKE CONCAT('%', #{query.phone}, '%')
ORDER BY COALESCE(display_order, 999999), updated_at DESC, created_at DESC
